import React from "react";
import {
  AbsoluteFill,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
  spring,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Initialize bold modern font
const { fontFamily: inter } = loadInter();



export type PodcastTrailerProps = Record<string, any>;

const PodcastTrailer: React.FC<PodcastTrailerProps> = ({
  backgroundColor = "#0A0A0A",
  transparentBackground = false,
  durationInSeconds = 8,
  textColor = "#FFFFFF",
  highlightColor = "#E6FF00", // Punchy kinetic yellow
  words = [
    { text: "STOP", isHighlight: true },
    { text: "SCROLLING.", isHighlight: false },
    { text: "THIS", isHighlight: false },
    { text: "IS", isHighlight: false },
    { text: "THE", isHighlight: false },
    { text: "ABSOLUTE", isHighlight: true },
    { text: "BEST", isHighlight: false },
    { text: "PODCAST", isHighlight: true },
    { text: "OF", isHighlight: false },
    { text: "THE", isHighlight: false },
    { text: "ENTIRE", isHighlight: true },
    { text: "YEAR.", isHighlight: false },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const totalFrames = durationInSeconds * fps;
  const s = Math.min(width, height);

  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  const totalItems = words.length;
  // Distribute words evenly across the duration
  const framesPerItem = totalFrames / Math.max(1, totalItems);

  // Global Pulse: A quick zoom bump every time a new word appears
  const currentBeatFrame = frame % framesPerItem;
  const globalPulseScale = interpolate(
    spring({
      fps,
      frame: currentBeatFrame,
      config: { damping: 14, stiffness: 250 },
    }),
    [0, 1],
    [1.04, 1]
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div
        style={{
          width: "100%",
          height: "100%",
          position: "relative",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          overflow: "hidden",
          transform: `scale(${globalPulseScale})`,
          transformOrigin: "center",
        }}
      >
        {words.map((item, i) => {
          const startFrame = i * framesPerItem;
          const endFrame = (i + 1) * framesPerItem;

          // Add a small overlap so the previous word fades out while the new one pops in
          const isActive =
            frame >= startFrame && frame <= endFrame + fps * 0.5;

          if (!isActive) return null;

          const localFrame = frame - startFrame;
          const exitFrame = frame - endFrame;

          // Intro: Aggressive kinetic pop-in
          const scaleIn = spring({
            fps,
            frame: localFrame,
            config: { damping: 11, stiffness: 220, mass: 0.8 },
          });

          // Exit: Fast scale out and fade (last word stays on screen)
          const isExiting = exitFrame > 0 && i !== totalItems - 1;
          const scaleOut = isExiting
            ? interpolate(exitFrame, [0, fps * 0.15], [1, 1.4], {
                extrapolateRight: "clamp",
              })
            : 1;
          const opacityOut = isExiting
            ? interpolate(exitFrame, [0, fps * 0.1], [1, 0], {
                extrapolateRight: "clamp",
              })
            : 1;

          const finalScale = scaleIn * scaleOut;

          // Kinetic rotation styling
          // Highlights get a larger tilt, standard text gets a subtle alternating tilt
          const isHighlight = item.isHighlight;
          const rotation = isHighlight ? -3 : i % 2 === 0 ? 1 : -1;

          // Dynamic styling for highlighted words
          const itemBg = isHighlight ? highlightColor : "transparent";
          const itemColor = isHighlight ? backgroundColor : textColor;
          const padding = isHighlight ? `${s * 0.02}px ${s * 0.05}px` : "0px";
          const borderRadius = isHighlight ? `${s * 0.015}px` : "0px";
          const baseFontSize = isHighlight ? s * 0.22 : s * 0.2;

          return (
            <AbsoluteFill
              key={i}
              style={{
                justifyContent: "center",
                alignItems: "center",
                zIndex: i,
              }}
            >
              <div
                style={{
                  fontFamily: inter,
                  fontWeight: 900,
                  fontSize: `${baseFontSize}px`,
                  color: itemColor,
                  backgroundColor: itemBg,
                  padding: padding,
                  borderRadius: borderRadius,
                  textTransform: "uppercase",
                  textAlign: "center",
                  lineHeight: 1,
                  maxWidth: "90%",
                  transform: `scale(${finalScale}) rotate(${rotation}deg)`,
                  opacity: opacityOut,
                  transition: "none",
                }}
              >
                {item.text}
              </div>
            </AbsoluteFill>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default PodcastTrailer;